INSERT INTO public.site_pages (slug, title, meta_description, is_published, show_in_nav, nav_order, nav_label, content)
VALUES (
  'massage-vs-kiropraktor-naprapat',
  'Massage, kiropraktor eller naprapat? – Så väljer du rätt i Uddevalla',
  'Massage, kiropraktor eller naprapat i Uddevalla? Vi förklarar skillnaderna och hjälper dig välja rätt behandling för rygg, nacke och muskelspänningar.',
  true,
  false,
  10,
  'Massage vs kiropraktor & naprapat',
  '[
    {"id":"b1","type":"heading","data":{"level":1,"text":"Massage, kiropraktor eller naprapat? – Så väljer du rätt i Uddevalla","showDivider":true}},
    {"id":"b2","type":"paragraph","data":{"text":"Värk i rygg, stel nacke eller spända axlar? I Uddevalla finns flera vägar till lindring – massage, kiropraktik och naprapati. De låter lika men arbetar på olika sätt. Här går vi igenom skillnaderna så att du kan välja den behandling som passar just dig."}},
    {"id":"b3","type":"heading","data":{"level":2,"text":"Vad gör en massageterapeut?"}},
    {"id":"b4","type":"paragraph","data":{"text":"En massageterapeut arbetar direkt med musklerna och den mjuka vävnaden. Genom strykningar, knådning och tryck löses spänningar upp, blodcirkulationen ökar och kroppen får möjlighet att återhämta sig. Klassisk massage är skonsam, avslappnande och fungerar väl både vid stress och vid muskulär värk – utan snabba manipulationer av lederna."}},
    {"id":"b5","type":"heading","data":{"level":2,"text":"Vad gör en kiropraktor?"}},
    {"id":"b6","type":"paragraph","data":{"text":"En kiropraktor fokuserar på leder och ryggrad. Behandlingen bygger ofta på snabba, riktade ledjusteringar (manipulationer) för att förbättra rörlighet och avlasta nerver. Kiropraktik riktar sig främst mot strukturella och ledrelaterade besvär snarare än mot själva muskelvävnaden."}},
    {"id":"b7","type":"heading","data":{"level":2,"text":"Vad gör en naprapat?"}},
    {"id":"b8","type":"paragraph","data":{"text":"En naprapat kombinerar arbete med både leder och muskler. Behandlingen kan innehålla mobilisering, manipulation, massage och stretching. Naprapati ligger på sätt och vis mellan massage och kiropraktik och används ofta vid mer sammansatta besvär i rörelseapparaten."}},
    {"id":"b9","type":"heading","data":{"level":2,"text":"Vilken behandling passar dig?"}},
    {"id":"b10","type":"list","data":{"items":["Vill du ha avslappning, stresslindring och mjuk muskelbehandling – välj massage.","Har du låsningar eller ledrelaterade besvär och vill ha justeringar – kiropraktor kan passa.","Har du sammansatta besvär i leder och muskler – naprapat arbetar med båda.","Är du osäker eller känslig för snabba manipulationer – massage är ett tryggt och skonsamt förstaval."]}},
    {"id":"b11","type":"heading","data":{"level":2,"text":"Massage hos Viriditas i Uddevalla"}},
    {"id":"b12","type":"paragraph","data":{"text":"Hos Viriditas möts du av Andreas Håman, diplomerad massageterapeut och certifierad massör. Andreas har en synnedsättning, vilket gett honom en ovanligt utvecklad känsla i händerna. Han läser av spänningar och muskelvävnad med en lyhördhet som ger en närvarande och individuellt anpassad behandling – en upplevelse som skiljer sig från strukturella justeringar hos kiropraktor eller naprapat."}},
    {"id":"b13","type":"paragraph","data":{"text":"Viriditas finns centralt i Uddevalla Folkets Hus, Göteborgsvägen 11B, och tar emot besökare från hela Bohuslän. Klassisk massage är dessutom godkänd som friskvård enligt Skatteverket – du kan använda ditt friskvårdsbidrag."}},
    {"id":"b14","type":"cta_button","data":{"text":"Boka massage i Uddevalla","trackSource":"guide-massage-vs-kiropraktor"}}
  ]'::jsonb
);